CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ language 'plpgsql';

CREATE TABLE IF NOT EXISTS usuario_politicas (
    id SERIAL PRIMARY KEY,
    usuario_id INTEGER NOT NULL,
    version VARCHAR(20) NOT NULL,
    aceptada_el TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_usuario_politicas_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT uk_usuario_version UNIQUE (usuario_id, version)
);

CREATE TABLE IF NOT EXISTS recepciones_mercancia (
    id SERIAL PRIMARY KEY,
    sede_receptora_id INTEGER NOT NULL,
    encargado_id INTEGER NOT NULL,
    empleado_id INTEGER NULL,
    administrador_id INTEGER NULL,
    estado VARCHAR(50) NOT NULL DEFAULT 'PENDIENTE_CONTEO' CHECK (estado IN ('PENDIENTE_CONTEO', 'CONTABILIZADO', 'DISTRIBUIDO', 'CANCELADO')),
    observaciones TEXT NULL,
    fecha_recepcion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_recepciones_sede FOREIGN KEY (sede_receptora_id) REFERENCES sedes(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_recepciones_encargado FOREIGN KEY (encargado_id) REFERENCES usuarios(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_recepciones_empleado FOREIGN KEY (empleado_id) REFERENCES usuarios(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_recepciones_administrador FOREIGN KEY (administrador_id) REFERENCES usuarios(id) ON DELETE RESTRICT ON UPDATE RESTRICT
);

CREATE TABLE IF NOT EXISTS recepcion_productos (
    id SERIAL PRIMARY KEY,
    recepcion_id INTEGER NOT NULL,
    codigo_sku VARCHAR(50) NOT NULL,
    cantidad_recibida DECIMAL(10,2) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_recepcion_productos_recepcion FOREIGN KEY (recepcion_id) REFERENCES recepciones_mercancia(id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT chk_recepcion_cantidad CHECK (cantidad_recibida > 0.00)
);

CREATE TABLE IF NOT EXISTS audit_logs (
    id SERIAL PRIMARY KEY,
    usuario_id INTEGER NULL,
    username VARCHAR(100) NOT NULL DEFAULT 'SISTEMA',
    accion VARCHAR(100) NOT NULL,
    detalles TEXT NULL,
    ip_address VARCHAR(50) NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_audit_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL ON UPDATE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_audit_logs_created_at ON audit_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_logs_usuario ON audit_logs(usuario_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_accion ON audit_logs(accion);

ALTER TABLE productos ADD COLUMN IF NOT EXISTS imagen_url VARCHAR(255);
ALTER TABLE categorias ADD COLUMN IF NOT EXISTS imagen_url VARCHAR(255);
